1262→// filterSessionsWithNewContent returns sessions that have new transcript content
1263→// beyond what was already condensed.
1264→// Computes the staged files list once and reuses it across all sessions to avoid
1265→// redundant `git diff --cached` calls (previously called up to 3 times per session).
1266→func (s *ManualCommitStrategy) filterSessionsWithNewContent(ctx context.Context, repo *git.Repository, sessions []*SessionState) []*SessionState {
1267→	var result []*SessionState
1268→
1269→	// Compute staged files once for all sessions.
1270→	// On error, pass nil — sessionHasNewContent treats nil stagedFiles as
1271→	// "unavailable" and skips overlap checks, falling through to other heuristics.
1272→	stagedFiles, err := getStagedFiles(ctx)
1273→	if err != nil {
1274→		logging.Debug(logging.WithComponent(ctx, "manual-commit"),
1275→			"filterSessionsWithNewContent: getStagedFiles failed, skipping overlap checks",
1276→			slog.String("error", err.Error()),
1277→		)
1278→		stagedFiles = nil
1279→	}
1280→
1281→	for _, state := range sessions {
1282→		// Skip fully-condensed ended sessions — no new content possible.
1283→		if state.FullyCondensed && state.Phase == session.PhaseEnded {
1284→			continue
1285→		}
1286→		hasNew, err := s.sessionHasNewContent(ctx, repo, state, contentCheckOpts{stagedFiles: stagedFiles})
1287→		if err != nil {
1288→			// On error, include the session (fail open for hooks)
1289→			result = append(result, state)
