// TestPostCommit_EndedSession_DifferentBaseCommit_Skipped verifies that an ENDED
// session whose BaseCommit differs from the parent of HEAD is completely skipped
// by PostCommit. The shadow-tree-based session discovery only finds sessions on
// the current shadow branch (parent of HEAD), so sessions from a different base
// commit epoch are structurally invisible — no loading, no processing, no overhead.
//
// This replaces the old force-condense approach: instead of detecting stale ENDED
// sessions via time threshold and force-condensing them, we simply never discover
// them in the first place. O(1) PostCommit regardless of accumulated session count.
func TestPostCommit_EndedSession_DifferentBaseCommit_Skipped(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// --- Create an ENDED session with carry-forward files at the initial HEAD ---
	endedSessionID := "ended-carry-forward"
	setupSessionWithCheckpoint(t, s, repo, dir, endedSessionID)

	endedState, err := s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	endedAt := time.Now().Add(-2 * time.Hour)
	endedState.Phase = session.PhaseEnded
	endedState.EndedAt = &endedAt
	endedState.FilesTouched = []string{"test.txt"}
	endedState.CheckpointTranscriptStart = 0
	originalStepCount := endedState.StepCount
	originalBaseCommit := endedState.BaseCommit
	require.NoError(t, s.saveSessionState(context.Background(), endedState))

	// Move HEAD forward with an unrelated commit (no trailer).
	// This changes HEAD, so the ENDED session's BaseCommit != parent of next HEAD.
	wt, err := repo.Worktree()
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(dir, "unrelated.txt"), []byte("unrelated work"), 0o644))
	_, err = wt.Add("unrelated.txt")
	require.NoError(t, err)
	_, err = wt.Commit("unrelated commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	// --- Create a NEW ACTIVE session at the new HEAD ---
	newSessionID := testNewActiveSessionID
	require.NoError(t, os.WriteFile(filepath.Join(dir, "new-feature.txt"), []byte("new feature content"), 0o644))

	metadataDir := ".entire/metadata/" + newSessionID
	metadataDirAbs := filepath.Join(dir, metadataDir)
	require.NoError(t, os.MkdirAll(metadataDirAbs, 0o755))

	transcript := `{"type":"human","message":{"content":"add new feature"}}
{"type":"assistant","message":{"content":"adding new feature"}}
`
	require.NoError(t, os.WriteFile(
		filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		[]byte(transcript), 0o644))

	err = s.SaveStep(context.Background(), StepContext{
		SessionID:      newSessionID,
		ModifiedFiles:  []string{},
		NewFiles:       []string{"new-feature.txt"},
		DeletedFiles:   []string{},
		MetadataDir:    metadataDir,
		MetadataDirAbs: metadataDirAbs,
		CommitMessage:  "Checkpoint: new feature",
		AuthorName:     "Test",
		AuthorEmail:    "test@test.com",
	})
	require.NoError(t, err)

	newState, err := s.loadSessionState(context.Background(), newSessionID)
	require.NoError(t, err)
	newState.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(context.Background(), newState))

	// --- Commit ONLY new-feature.txt (not test.txt) with checkpoint trailer ---
	wt, err = repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("new-feature.txt")
	require.NoError(t, err)

	cpID := "ae1ae2ae3ae4"
	commitMsg := "add new feature\n\n" + trailers.CheckpointTrailerKey + ": " + cpID + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)
	newHead := head.Hash().String()

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// --- Verify: ENDED session was SKIPPED (different BaseCommit) ---
	endedState, err = s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)

	// StepCount should be unchanged — session was never discovered
	assert.Equal(t, originalStepCount, endedState.StepCount,
		"ENDED session StepCount should be unchanged (skipped due to different BaseCommit)")

	// BaseCommit should be unchanged — ENDED sessions don't get base commit updates
	assert.Equal(t, originalBaseCommit, endedState.BaseCommit,
		"ENDED session BaseCommit should be unchanged (skipped)")

	// FilesTouched should be preserved
	assert.Equal(t, []string{"test.txt"}, endedState.FilesTouched,
		"ENDED session FilesTouched should be preserved (skipped)")

	// Phase stays ENDED
	assert.Equal(t, session.PhaseEnded, endedState.Phase,
		"ENDED session should remain ENDED")

	// NOT marked FullyCondensed — it was never processed
	assert.False(t, endedState.FullyCondensed,
		"ENDED session should NOT be marked FullyCondensed (skipped)")

	// --- Verify: new ACTIVE session WAS condensed ---
	newState, err = s.loadSessionState(context.Background(), newSessionID)
	require.NoError(t, err)
	assert.Equal(t, 0, newState.StepCount,
		"New ACTIVE session StepCount should be reset by condensation")
	assert.Equal(t, newHead, newState.BaseCommit,
		"New ACTIVE session BaseCommit should be updated after condensation")
}

// TestPostCommit_EndedSession_SameBaseCommit_ProcessedNormally verifies that an
// ENDED session whose BaseCommit matches the parent of HEAD (same shadow branch)
// is still discovered and processed normally by PostCommit. The shadow-tree-based
// approach finds it because its metadata exists on the current shadow branch.
func TestPostCommit_EndedSession_SameBaseCommit_ProcessedNormally(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// Create ENDED session at current HEAD (same base commit)
	endedSessionID := "ended-same-base"
	setupSessionWithCheckpoint(t, s, repo, dir, endedSessionID)

	endedState, err := s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	endedAt := time.Now().Add(-5 * time.Minute)
	endedState.Phase = session.PhaseEnded
	endedState.EndedAt = &endedAt
	endedState.FilesTouched = []string{"test.txt"}
	endedState.CheckpointTranscriptStart = 0
	require.NoError(t, s.saveSessionState(context.Background(), endedState))

	originalStepCount := endedState.StepCount

	// Commit test.txt (overlaps with ENDED session's files) with checkpoint trailer.
	// The ENDED session's BaseCommit == parent of this new commit, so it's on the
	// current shadow branch and will be discovered.
	commitWithCheckpointTrailer(t, repo, dir, "rc01rc02rc03")

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify: ENDED session on same shadow branch was discovered and condensed
	endedState, err = s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	// StepCount reset means condensation happened
	assert.Equal(t, 0, endedState.StepCount,
		"StepCount should be reset — session was discovered on same shadow branch and condensed")
	assert.NotEqual(t, originalStepCount, 0,
		"Original StepCount should have been non-zero (checkpoint was created)")
	assert.True(t, endedState.FullyCondensed,
		"ENDED session should be marked FullyCondensed after condensation")
}

