//go:build integration

package integration

import (
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/session"
)

// TestCarryForward_EndedSessionDifferentBaseCommit_Skipped verifies that when
// an old ENDED session has carry-forward files and HEAD has moved forward via
// unrelated commits, the old session is completely skipped by PostCommit.
//
// With shadow-tree-based session discovery (GitHub issue #591 fix), PostCommit
// only discovers sessions whose BaseCommit == parent of HEAD. ENDED sessions
// whose BaseCommit diverged are structurally invisible — no loading, no
// processing, no overhead. O(1) PostCommit regardless of accumulated session count.
//
// Scenario:
// 1. Session 1 creates file1.txt and file2.txt
// 2. User commits only file1.txt (partial commit)
// 3. Session 1 gets carry-forward: FilesTouched = ["file2.txt"]
// 4. Session 1 ends
// 5. Make some unrelated commits (HEAD moves forward)
// 6. New session 2 creates and commits file6.txt
// 7. Verify: Session 1 was SKIPPED (different BaseCommit) — state unchanged
// 8. Verify: Session 2 WAS condensed normally
func TestCarryForward_EndedSessionDifferentBaseCommit_Skipped(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	// ========================================
	// Setup
	// ========================================
	env.InitRepo()
	env.WriteFile("README.md", "# Test Repository")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/multi-session-carry-forward")
	env.InitEntire()

	// ========================================
	// Phase 1: Session 1 creates files, partial commit, ends with carry-forward
	// ========================================
	t.Log("Phase 1: Session 1 creates file1.txt and file2.txt")

	session1 := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session1.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit for session1 failed: %v", err)
	}

	env.WriteFile("file1.txt", "content from session 1 - file 1")
	env.WriteFile("file2.txt", "content from session 1 - file 2")
	session1.CreateTranscript(
		"Create file1 and file2",
		[]FileChange{
			{Path: "file1.txt", Content: "content from session 1 - file 1"},
			{Path: "file2.txt", Content: "content from session 1 - file 2"},
		},
	)
	if err := env.SimulateStop(session1.ID, session1.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop for session1 failed: %v", err)
	}

	// Partial commit - only file1.txt
	t.Log("Phase 1b: Partial commit - only file1.txt")
	env.GitAdd("file1.txt")
	env.GitCommitWithShadowHooks("Partial commit: only file1", "file1.txt")

	// End session 1 (set phase to ENDED, no time manipulation needed)
	state1, err := env.GetSessionState(session1.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session1 failed: %v", err)
	}
	state1.Phase = session.PhaseEnded
	if err := env.WriteSessionState(session1.ID, state1); err != nil {
		t.Fatalf("WriteSessionState for session1 failed: %v", err)
	}

	// Verify carry-forward exists
	state1, err = env.GetSessionState(session1.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session1 failed: %v", err)
	}
	t.Logf("Session1 (ENDED) FilesTouched: %v", state1.FilesTouched)

	// Record session 1 state before further commits for comparison
	state1StepCount := state1.StepCount

	// ========================================
	// Phase 2: Make some unrelated commits (HEAD moves forward)
	// ========================================
	t.Log("Phase 2: Making unrelated commits (moves HEAD away from session 1 BaseCommit)")

	for _, fileName := range []string{"file3.txt", "file4.txt"} {
		env.WriteFile(fileName, "unrelated content")
		env.GitAdd(fileName)
		env.GitCommitWithShadowHooks("Add "+fileName, fileName)
	}

	// ========================================
	// Phase 3: NEW session 2 starts and creates file6.txt
	// ========================================
	t.Log("Phase 3: Session 2 starts and creates file6.txt")

	session2 := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session2.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit for session2 failed: %v", err)
	}

	env.WriteFile("file6.txt", "content from session 2")
	session2.CreateTranscript(
		"Create file6",
		[]FileChange{{Path: "file6.txt", Content: "content from session 2"}},
	)
	if err := env.SimulateStop(session2.ID, session2.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop for session2 failed: %v", err)
	}

	// Set session2 to ACTIVE
	state2, err := env.GetSessionState(session2.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session2 failed: %v", err)
	}
	state2.Phase = session.PhaseActive
	if err := env.WriteSessionState(session2.ID, state2); err != nil {
		t.Fatalf("WriteSessionState for session2 failed: %v", err)
	}

	// ========================================
	// Phase 4: Commit file6.txt (session 2's file)
	// ========================================
	t.Log("Phase 4: Committing file6.txt from session 2")

	env.GitAdd("file6.txt")
	env.GitCommitWithShadowHooks("Add file6 from session 2", "file6.txt")

	finalHead := env.GetHeadHash()

	// ========================================
	// Phase 5: Verify session 1 was SKIPPED (different BaseCommit)
	// ========================================
	t.Log("Phase 5: Verifying session 1 (ENDED, different BaseCommit) was skipped")

	state1After, err := env.GetSessionState(session1.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session1 after session2 commit failed: %v", err)
	}

	// StepCount should be UNCHANGED (session was never discovered/processed)
	if state1After.StepCount != state1StepCount {
		t.Errorf("Session 1 StepCount should be unchanged (%d), got %d", state1StepCount, state1After.StepCount)
	}

	// FilesTouched should still have carry-forward files (not cleared)
	if len(state1After.FilesTouched) == 0 {
		t.Errorf("Session 1 FilesTouched should be preserved (skipped), got empty")
	}

	// NOT FullyCondensed (never processed)
	if state1After.FullyCondensed {
		t.Errorf("Session 1 should NOT be marked FullyCondensed (was skipped, not condensed)")
	}

	t.Logf("Session 1 correctly skipped: StepCount=%d, FilesTouched=%v, FullyCondensed=%v",
		state1After.StepCount, state1After.FilesTouched, state1After.FullyCondensed)

	// ========================================
	// Phase 6: Verify session 2 WAS condensed
	// ========================================
	t.Log("Phase 6: Verifying session 2 WAS condensed")

	state2After, err := env.GetSessionState(session2.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session2 after commit failed: %v", err)
	}

	if state2After.BaseCommit != finalHead {
		t.Errorf("Session 2 BaseCommit should be updated. Expected %s, got %s",
			finalHead[:7], state2After.BaseCommit[:7])
	}

	t.Log("Test completed successfully:")
	t.Log("  - Session 1 skipped (different BaseCommit, structurally invisible)")
	t.Log("  - Session 2 condensed normally")
}

//go:build integration

package integration

import (
	"fmt"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/session"
)

// TestSubagentAccumulation_Issue591 verifies the issue #591 fix: multiple
// subagent sessions that end with uncommitted files do not cause O(N) overhead
// on every future commit. With shadow-tree-based session discovery, ENDED
// sessions whose BaseCommit differs from parent of HEAD are never discovered.
//
// The eager condense on session stop (CondenseAndMarkFullyCondensed) handles
// sessions with no FilesTouched. Sessions WITH FilesTouched are discovered only
// when their BaseCommit matches the current shadow branch; once HEAD moves
// forward, they become structurally invisible.
func TestSubagentAccumulation_Issue591(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)

	type subagentInfo struct {
		SessionID string
		File      string
	}

	t.Log("Phase 1: start parent session and create ended subagent sessions")

	parent := env.NewSession()
	if err := env.SimulateUserPromptSubmit(parent.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit for parent failed: %v", err)
	}
	parent.TranscriptBuilder.AddUserMessage("Use subagents to investigate the work and then create the parent file.")

	const numSubagents = 4
	subagents := make([]subagentInfo, 0, numSubagents)

	for i := 0; i < numSubagents; i++ {
		sub := env.NewSession()
		file := fmt.Sprintf("subagent_work_%d.go", i)
		content := fmt.Sprintf("package main\n\nfunc SubagentWork%d() {}\n", i)

		if err := env.SimulateUserPromptSubmit(sub.ID); err != nil {
			t.Fatalf("SimulateUserPromptSubmit for subagent %d failed: %v", i, err)
		}

		env.WriteFile(file, content)
		sub.CreateTranscript("Create "+file, []FileChange{
			{Path: file, Content: content},
		})

		if err := env.SimulateStop(sub.ID, sub.TranscriptPath); err != nil {
			t.Fatalf("SimulateStop for subagent %d failed: %v", i, err)
		}
		if err := env.SimulateSessionEnd(sub.ID); err != nil {
			t.Fatalf("SimulateSessionEnd for subagent %d failed: %v", i, err)
		}

		state, err := env.GetSessionState(sub.ID)
		if err != nil {
			t.Fatalf("GetSessionState for subagent %d failed: %v", i, err)
		}
		if state == nil {
			t.Fatalf("subagent %d session state missing", i)
		}
		if state.Phase != session.PhaseEnded {
			t.Fatalf("subagent %d phase = %s, want ended", i, state.Phase)
		}
		if len(state.FilesTouched) == 0 {
			t.Fatalf("subagent %d FilesTouched should be non-empty before cleanup", i)
		}
		if state.StepCount == 0 {
			t.Fatalf("subagent %d StepCount should be > 0 before cleanup", i)
		}
		// CondenseAndMarkFullyCondensed skips sessions with FilesTouched,
		// so the subagent should NOT be FullyCondensed yet.
		if state.FullyCondensed {
			t.Fatalf("subagent %d should not be FullyCondensed before cleanup (has FilesTouched)", i)
		}

		taskToolUseID := fmt.Sprintf("toolu_parent_subagent_%d", i)
		parent.TranscriptBuilder.AddTaskToolUse(taskToolUseID, "Create "+file)
		parent.TranscriptBuilder.AddTaskToolResult(taskToolUseID, sub.ID)

		subagents = append(subagents, subagentInfo{
			SessionID: sub.ID,
			File:      file,
		})
	}

	t.Log("Phase 2: parent commits unrelated work")

	parentFile := "parent_work.go"
	parentContent := "package main\n\nfunc ParentWork() {}\n"
	env.WriteFile(parentFile, parentContent)
	parentToolUseID := parent.TranscriptBuilder.AddToolUse("mcp__acp__Write", parentFile, parentContent)
	parent.TranscriptBuilder.AddToolResult(parentToolUseID)
	parent.TranscriptBuilder.AddAssistantMessage("Done.")
	if err := parent.TranscriptBuilder.WriteToFile(parent.TranscriptPath); err != nil {
		t.Fatalf("failed to write parent transcript: %v", err)
	}

	if err := env.SimulateStop(parent.ID, parent.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop for parent failed: %v", err)
	}

	env.GitCommitWithShadowHooks("Parent commit", parentFile)

	t.Log("Phase 3: verify ended subagent sessions were discovered but not condensed (no file overlap)")

	// The subagent sessions share the same BaseCommit as the parent commit's
	// parent (same shadow branch), so they ARE discovered by PostCommit. But
	// their files don't overlap with the committed file, so HandleCondenseIfFilesTouched
	// does not condense them. Their state is unchanged (updateBaseCommitIfChanged
	// skips non-active sessions).
	for i, sub := range subagents {
		state, err := env.GetSessionState(sub.SessionID)
		if err != nil {
			t.Fatalf("GetSessionState after parent commit for subagent %d failed: %v", i, err)
		}
		if state == nil {
			t.Fatalf("subagent %d session state missing after parent commit", i)
		}
		if state.Phase != session.PhaseEnded {
			t.Fatalf("subagent %d phase after parent commit = %s, want ended", i, state.Phase)
		}
		// NOT condensed (no file overlap with committed files)
		if state.FullyCondensed {
			t.Fatalf("subagent %d should NOT be FullyCondensed after parent commit (no file overlap)", i)
		}
		// FilesTouched preserved (no condensation happened)
		if len(state.FilesTouched) == 0 {
			t.Fatalf("subagent %d FilesTouched should be preserved (not condensed)", i)
		}
	}

	t.Log("Phase 4: make another commit and verify subagents are structurally skipped (different BaseCommit)")

	followUp := env.NewSession()
	if err := env.SimulateUserPromptSubmit(followUp.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit for follow-up session failed: %v", err)
	}

	followUpFile := "follow_up.go"
	followUpContent := "package main\n\nfunc FollowUp() {}\n"
	env.WriteFile(followUpFile, followUpContent)
	followUp.CreateTranscript("Create "+followUpFile, []FileChange{
		{Path: followUpFile, Content: followUpContent},
	})
	if err := env.SimulateStop(followUp.ID, followUp.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop for follow-up session failed: %v", err)
	}

	env.GitCommitWithShadowHooks("Follow-up commit", followUpFile)

	// After the follow-up commit, subagent sessions' BaseCommit != parent of
	// the new HEAD (HEAD moved forward). They are structurally invisible to
	// PostCommit and never loaded/processed. State remains unchanged.
	for i, sub := range subagents {
		state, err := env.GetSessionState(sub.SessionID)
		if err != nil {
			t.Fatalf("GetSessionState after follow-up commit for subagent %d failed: %v", i, err)
		}
		if state == nil {
			t.Fatalf("subagent %d session state missing after follow-up commit", i)
		}
		// Still NOT FullyCondensed — structurally skipped, not processed
		if state.FullyCondensed {
			t.Fatalf("subagent %d should NOT be FullyCondensed after follow-up commit (different BaseCommit, skipped)", i)
		}
		// FilesTouched still present
		if len(state.FilesTouched) == 0 {
			t.Fatalf("subagent %d FilesTouched should be preserved after follow-up commit", i)
		}
	}
}

