247→// extractSessionIDsFromTree reads the shadow branch tree to find session IDs
248→// stored under .entire/metadata/<session-id>/ directories.
249→func extractSessionIDsFromTree(tree *object.Tree) []string {
250→	// Navigate to .entire/metadata subtree
251→	metadataTree, err := tree.Tree(paths.EntireMetadataDir)
252→	if err != nil {
253→		return nil
254→	}
255→
256→	var sessionIDs []string
257→	for _, entry := range metadataTree.Entries {
258→		// Session IDs are directory entries under .entire/metadata/
259→		if entry.Mode == filemode.Dir {

260→			sessionIDs = append(sessionIDs, entry.Name)
261→		}
262→	}
263→	return sessionIDs
264→}
265→
266→// findSessionsForCommit finds all sessions where base_commit matches the given SHA.
267→func (s *ManualCommitStrategy) findSessionsForCommit(ctx context.Context, baseCommitSHA string) ([]*SessionState, error) {
268→	allStates, err := s.listAllSessionStates(ctx)
269→	if err != nil {
270→		return nil, err
271→	}
272→
273→	var matching []*SessionState
274→	for _, state := range allStates {
275→		if state.BaseCommit == baseCommitSHA {
276→			matching = append(matching, state)
277→		}
278→	}
279→	return matching, nil
280→}
281→
282→// FindSessionsForCommit is the exported version of findSessionsForCommit.
283→// Used by the rewind reset command to find sessions to clean up.
284→func (s *ManualCommitStrategy) FindSessionsForCommit(ctx context.Context, baseCommitSHA string) ([]*SessionState, error) {
285→	return s.findSessionsForCommit(ctx, baseCommitSHA)
286→}
