125→		if state == nil {
126→			t.Fatalf("subagent %d session state missing after parent commit", i)
127→		}
128→		if state.Phase != session.PhaseEnded {
129→			t.Fatalf("subagent %d phase after parent commit = %s, want ended", i, state.Phase)
130→		}
131→		// NOT condensed (no file overlap with committed files)
132→		if state.FullyCondensed {
133→			t.Fatalf("subagent %d should NOT be FullyCondensed after parent commit (no file overlap)", i)
134→		}
135→		// FilesTouched preserved (no condensation happened)
136→		if len(state.FilesTouched) == 0 {
137→			t.Fatalf("subagent %d FilesTouched should be preserved (not condensed)", i)
138→		}
139→	}
140→
141→	t.Log("Phase 4: make another commit and verify subagents are structurally skipped (different BaseCommit)")
142→
143→	followUp := env.NewSession()
144→	if err := env.SimulateUserPromptSubmit(followUp.ID); err != nil {
145→		t.Fatalf("SimulateUserPromptSubmit for follow-up session failed: %v", err)
146→	}
147→
148→	followUpFile := "follow_up.go"
149→	followUpContent := "package main\n\nfunc FollowUp() {}\n"
150→	env.WriteFile(followUpFile, followUpContent)
151→	followUp.CreateTranscript("Create "+followUpFile, []FileChange{
152→		{Path: followUpFile, Content: followUpContent},
153→	})
154→	if err := env.SimulateStop(followUp.ID, followUp.TranscriptPath); err != nil {
155→		t.Fatalf("SimulateStop for follow-up session failed: %v", err)
156→	}
157→
158→	env.GitCommitWithShadowHooks("Follow-up commit", followUpFile)
159→
160→	// After the follow-up commit, subagent sessions are either:
161→	// (a) cleaned up by listAllSessionStates (shadow branch was deleted after
162→	//     parent commit condensation, sessions are orphaned with no LastCheckpointID), or
163→	// (b) still present but NOT FullyCondensed (structurally invisible to PostCommit
164→	//     because their BaseCommit != parent of the new HEAD).
165→	// Either outcome is acceptable — the key property is that they impose zero
166→	// overhead on the follow-up commit's PostCommit.
167→	for i, sub := range subagents {
168→		state, err := env.GetSessionState(sub.SessionID)
169→		if err != nil {
170→			t.Fatalf("GetSessionState after follow-up commit for subagent %d failed: %v", i, err)
171→		}
172→		if state == nil {
173→			// State file was cleaned up — this is fine (orphaned session cleanup)
174→			t.Logf("subagent %d state file cleaned up (orphaned shadow branch)", i)
175→			continue
176→		}
177→		// If still present: NOT FullyCondensed (was skipped, not processed)
178→		if state.FullyCondensed {
179→			t.Fatalf("subagent %d should NOT be FullyCondensed after follow-up commit (different BaseCommit, skipped)", i)
180→		}
181→	}
182→}
