 26→// loadSessionState loads session state using the StateStore.
 27→func (s *ManualCommitStrategy) loadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
 28→	store, err := s.getStateStore(ctx)
 29→	if err != nil {
 30→		return nil, err
 31→	}
 32→	state, err := store.Load(ctx, sessionID)
 33→	if err != nil {
 34→		return nil, fmt.Errorf("failed to load session state: %w", err)
 35→	}
 36→	return state, nil
 37→}
