 39→// saveSessionState saves session state using the StateStore.
 40→func (s *ManualCommitStrategy) saveSessionState(ctx context.Context, state *SessionState) error {
 41→	store, err := s.getStateStore(ctx)
 42→	if err != nil {
 43→		return err
 44→	}
 45→	if err := store.Save(ctx, state); err != nil {
 46→		return fmt.Errorf("failed to save session state: %w", err)
 47→	}
 48→	return nil
 49→}
