 51→// clearSessionState clears session state using the StateStore.
 52→func (s *ManualCommitStrategy) clearSessionState(ctx context.Context, sessionID string) error {
 53→	store, err := s.getStateStore(ctx)
 54→	if err != nil {
 55→		return err
 56→	}
 57→	if err := store.Clear(ctx, sessionID); err != nil {
 58→		return fmt.Errorf("failed to clear session state: %w", err)
