 63→// listAllSessionStates returns all active session states.
 64→// It filters out orphaned sessions whose shadow branch no longer exists.
 65→func (s *ManualCommitStrategy) listAllSessionStates(ctx context.Context) ([]*SessionState, error) {
 66→	store, err := s.getStateStore(ctx)
 67→	if err != nil {
 68→		return nil, fmt.Errorf("failed to get state store: %w", err)
 69→	}
 70→
 71→	sessionStates, err := store.List(ctx)
 72→	if err != nil {
 73→		return nil, fmt.Errorf("failed to list session states: %w", err)
 74→	}
 75→
 76→	if len(sessionStates) == 0 {
 77→		return nil, nil
 78→	}
 79→
 80→	repo, err := OpenRepository(ctx)
 81→	if err != nil {
 82→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 83→	}
 84→
 85→	var states []*SessionState
 86→	for _, sessionState := range sessionStates {
 87→		state := sessionState
 88→
 89→		// Skip and cleanup orphaned sessions whose shadow branch no longer exists.
 90→		// Keep active sessions (shadow branch may not be created yet) and sessions
 91→		// with LastCheckpointID (needed for checkpoint ID reuse on subsequent commits).
 92→		// Clean up everything else: stale pre-state-machine sessions (empty phase),
 93→		// IDLE/ENDED sessions that were never condensed, etc.
 94→		shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
 95→		refName := plumbing.NewBranchReferenceName(shadowBranch)
 96→		if _, err := repo.Reference(refName, true); err != nil {
 97→			if !state.Phase.IsActive() && state.LastCheckpointID.IsEmpty() {
 98→				//nolint:errcheck,gosec // G104: Cleanup is best-effort, shouldn't fail the list operation
 99→				store.Clear(ctx, state.SessionID)
100→				continue
101→			}
102→		}
103→
104→		states = append(states, state)
105→	}
106→	return states, nil
107→}
