109→// findSessionsForWorktree finds all sessions for the given worktree path.
110→func (s *ManualCommitStrategy) findSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
111→	allStates, err := s.listAllSessionStates(ctx)
112→	if err != nil {
113→		return nil, err
114→	}
115→
116→	var matching []*SessionState
117→	for _, state := range allStates {
118→		if state.WorktreePath == worktreePath {
119→			matching = append(matching, state)
120→		}
121→	}
