125→// findSessionsFromShadowTree discovers sessions relevant to a PostCommit by using
126→// the shadow branch tree as an index. Instead of loading ALL state files and doing
127→// N ref lookups (O(N) in total session count), this:
128→//
129→//  1. Computes the shadow branch name from parentCommitHash + worktreePath
130→//  2. Single ref lookup to resolve the shadow branch
131→//  3. Lists .entire/metadata/* entries in the shadow tree to extract session IDs
132→//  4. Loads only those session state files
133→//  5. Also loads any ACTIVE sessions from state files that might not have shadow
134→//     branch data yet (they may not have had a SaveStep yet)
135→//
136→// This gives O(1) PostCommit cost regardless of total accumulated session count,
137→// because only sessions on the current shadow branch are processed.
138→func (s *ManualCommitStrategy) findSessionsFromShadowTree(ctx context.Context, repo *git.Repository, parentCommitHash, worktreePath string) ([]*SessionState, error) {
139→	logCtx := logging.WithComponent(ctx, "checkpoint")
140→
141→	// Compute worktree ID and shadow branch name
142→	worktreeID, err := paths.GetWorktreeID(worktreePath)
143→	if err != nil {
144→		return nil, fmt.Errorf("failed to get worktree ID: %w", err)
145→	}
146→
147→	seen := make(map[string]bool)
148→	var sessions []*SessionState
149→
150→	// Step 1: Find sessions from the shadow branch tree
151→	if parentCommitHash != "" {
152→		shadowBranch := checkpoint.ShadowBranchNameForCommit(parentCommitHash, worktreeID)
153→		refName := plumbing.NewBranchReferenceName(shadowBranch)
154→		if ref, refErr := repo.Reference(refName, true); refErr == nil {
155→			if commitObj, cErr := repo.CommitObject(ref.Hash()); cErr == nil {
156→				if tree, tErr := commitObj.Tree(); tErr == nil {
157→					sessionIDs := extractSessionIDsFromTree(tree)
158→					for _, sessionID := range sessionIDs {
159→						if seen[sessionID] {
160→							continue
161→						}
162→						state, loadErr := s.loadSessionState(ctx, sessionID)
163→						if loadErr != nil || state == nil {
164→							continue
165→						}
166→						// Skip fully-condensed ended sessions early
167→						if state.FullyCondensed && state.Phase == session.PhaseEnded {
168→							continue
169→						}
170→						seen[sessionID] = true
171→						sessions = append(sessions, state)
172→					}
173→				}
174→			}
175→		}
176→	}
177→
178→	// Step 2: Scan state files for sessions not yet in the shadow tree.
179→	// This catches two cases:
180→	//   a) ACTIVE sessions that haven't had SaveStep yet (no shadow branch data)
181→	//   b) Non-active sessions with carry-forward files whose BaseCommit matches
182→	//      the parent commit. Carry-forward shadow branches intentionally omit
183→	//      metadata (to avoid sessionHasNewContent false positives), so these
184→	//      sessions are invisible to the shadow tree scan above.
185→	// This is cheap — just JSON parse + field checks, no ref lookups.
186→	store, storeErr := s.getStateStore(ctx)
187→	if storeErr != nil {
188→		logging.Warn(logCtx, "findSessionsFromShadowTree: failed to get state store",
189→			slog.String("error", storeErr.Error()))
190→		return sessions, nil
191→	}
192→	allStates, listErr := store.List(ctx)
193→	if listErr != nil {
194→		logging.Warn(logCtx, "findSessionsFromShadowTree: failed to list session states",
195→			slog.String("error", listErr.Error()))
196→		return sessions, nil
197→	}
198→	for _, state := range allStates {
199→		if seen[state.SessionID] {
200→			continue
201→		}
202→		if state.WorktreePath != worktreePath {
203→			continue
204→		}
205→		// Case (a): ACTIVE sessions without shadow branch data
206→		if state.Phase.IsActive() {
207→			seen[state.SessionID] = true
208→			sessions = append(sessions, state)
209→			continue
210→		}
211→		// Case (b): Non-active sessions with carry-forward files on this shadow branch
212→		if parentCommitHash != "" && state.BaseCommit == parentCommitHash && len(state.FilesTouched) > 0 {
213→			if state.FullyCondensed && state.Phase == session.PhaseEnded {
214→				continue
215→			}
216→			seen[state.SessionID] = true
217→			sessions = append(sessions, state)
218→		}
219→	}
220→
221→	return sessions, nil
222→}
