224→// findActiveSessionsForWorktree scans state files and returns only ACTIVE-phase
225→// sessions for the given worktree. This is cheap — no ref lookups needed, just
226→// JSON parse + phase check.
227→func (s *ManualCommitStrategy) findActiveSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
228→	store, err := s.getStateStore(ctx)
229→	if err != nil {
230→		return nil, fmt.Errorf("failed to get state store: %w", err)
231→	}
232→
233→	allStates, err := store.List(ctx)
234→	if err != nil {
235→		return nil, fmt.Errorf("failed to list session states: %w", err)
236→	}
237→
238→	var matching []*SessionState
239→	for _, state := range allStates {
240→		if state.Phase.IsActive() && state.WorktreePath == worktreePath {
241→			matching = append(matching, state)
242→		}
243→	}
244→	return matching, nil
245→}
