294→// CountOtherActiveSessionsWithCheckpoints counts how many other active sessions
295→// from the SAME worktree (different from currentSessionID) have created checkpoints
296→// on the SAME base commit (current HEAD). This is used to show an informational message
297→// about concurrent sessions that will be included in the next commit.
298→// Returns 0, nil if no such sessions exist.
299→func (s *ManualCommitStrategy) CountOtherActiveSessionsWithCheckpoints(ctx context.Context, currentSessionID string) (int, error) {
300→	currentWorktree, err := paths.WorktreeRoot(ctx)
301→	if err != nil {
302→		return 0, fmt.Errorf("failed to get worktree root: %w", err)
303→	}
304→
305→	// Get current HEAD to compare with session base commits
306→	repo, err := OpenRepository(ctx)
307→	if err != nil {
308→		return 0, err
309→	}
310→	head, err := repo.Head()
311→	if err != nil {
312→		return 0, fmt.Errorf("failed to get HEAD: %w", err)
313→	}
314→	currentHead := head.Hash().String()
315→
316→	allStates, err := s.listAllSessionStates(ctx)
317→	if err != nil {
318→		return 0, err
319→	}
320→
321→	count := 0
322→	for _, state := range allStates {
323→		// Only consider sessions from the same worktree with checkpoints
324→		// AND based on the same commit (current HEAD)
325→		// Sessions from different base commits are independent and shouldn't be counted
326→		if state.SessionID != currentSessionID &&
327→			state.WorktreePath == currentWorktree &&
328→			state.StepCount > 0 &&
329→			state.BaseCommit == currentHead {
330→			count++
331→		}
332→	}
333→	return count, nil
334→}
