// TestPostCommit_EndedSession_SameBaseCommit_NoOverlap_NotCondensed verifies that
// an ENDED session with carry-forward files on the same shadow branch is NOT
// condensed when the committed files do not overlap with the session's FilesTouched.
// The overlap check prevents unrelated commits from consuming carry-forward state.
func TestPostCommit_EndedSession_SameBaseCommit_NoOverlap_NotCondensed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// Create ENDED session at current HEAD (same base commit)
	endedSessionID := "ended-no-overlap"
	setupSessionWithCheckpoint(t, s, repo, dir, endedSessionID)

	endedState, err := s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	endedAt := time.Now().Add(-5 * time.Minute)
	endedState.Phase = session.PhaseEnded
	endedState.EndedAt = &endedAt
	endedState.FilesTouched = []string{"test.txt"}
	endedState.CheckpointTranscriptStart = 0
	require.NoError(t, s.saveSessionState(context.Background(), endedState))

	originalStepCount := endedState.StepCount
	originalFilesTouched := make([]string, len(endedState.FilesTouched))
	copy(originalFilesTouched, endedState.FilesTouched)

	// Commit an UNRELATED file (no overlap with session's FilesTouched ["test.txt"]).
	// Use a checkpoint trailer so PostCommit processes this commit.
	cpID := id.MustCheckpointID("bb01bb02bb03")
	unrelatedFile := filepath.Join(dir, "unrelated.txt")
	require.NoError(t, os.WriteFile(unrelatedFile, []byte("unrelated content"), 0o644))

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("unrelated.txt")
	require.NoError(t, err)

	commitMsg := "unrelated commit\n\n" + trailers.CheckpointTrailerKey + ": " + cpID.String() + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  time.Now(),
		},
	})
	require.NoError(t, err)

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify: ENDED session was NOT condensed because committed files don't overlap
	endedState, err = s.loadSessionState(context.Background(), endedSessionID)
	require.NoError(t, err)
	assert.Equal(t, originalStepCount, endedState.StepCount,
		"StepCount should be unchanged — no overlap means no condensation")
	assert.False(t, endedState.FullyCondensed,
		"ENDED session should NOT be marked FullyCondensed (no overlap, not condensed)")
	assert.Equal(t, originalFilesTouched, endedState.FilesTouched,
		"FilesTouched should be preserved for future commits that do overlap")
}

