125→// findSessionsFromShadowTree discovers sessions relevant to a PostCommit by using
126→// the shadow branch tree as an index. Instead of loading ALL state files and doing
127→// N ref lookups (O(N) in total session count), this:
128→//
129→//  1. Computes the shadow branch name from parentCommitHash + worktreePath
130→//  2. Single ref lookup to resolve the shadow branch
131→//  3. Lists .entire/metadata/* entries in the shadow tree to extract session IDs
132→//  4. Loads only those session state files
133→//  5. Also loads any ACTIVE sessions from state files that might not have shadow
134→//     branch data yet (they may not have had a SaveStep yet)
135→//
136→// This gives O(1) cost in git ref lookups regardless of total accumulated session
137→// count, because only sessions on the current shadow branch are processed.
138→// Step 2 scans all state files, but this is cheap (JSON parse + field checks only,
139→// no git operations).
140→func (s *ManualCommitStrategy) findSessionsFromShadowTree(ctx context.Context, repo *git.Repository, parentCommitHash, worktreePath string) ([]*SessionState, error) {
141→	logCtx := logging.WithComponent(ctx, "checkpoint")
142→
143→	// Compute worktree ID and shadow branch name
144→	worktreeID, err := paths.GetWorktreeID(worktreePath)
145→	if err != nil {
146→		return nil, fmt.Errorf("failed to get worktree ID: %w", err)
147→	}
148→
149→	seen := make(map[string]bool)
150→	var sessions []*SessionState
151→
152→	// Step 1: Find sessions from the shadow branch tree
153→	if parentCommitHash != "" {
154→		shadowBranch := checkpoint.ShadowBranchNameForCommit(parentCommitHash, worktreeID)
155→		refName := plumbing.NewBranchReferenceName(shadowBranch)
156→		if ref, refErr := repo.Reference(refName, true); refErr == nil {
157→			if commitObj, cErr := repo.CommitObject(ref.Hash()); cErr == nil {
158→				if tree, tErr := commitObj.Tree(); tErr == nil {
159→					sessionIDs := extractSessionIDsFromTree(tree)
160→					for _, sessionID := range sessionIDs {
161→						if seen[sessionID] {
162→							continue
163→						}
164→						state, loadErr := s.loadSessionState(ctx, sessionID)
165→						if loadErr != nil || state == nil {
166→							continue
167→						}
168→						// Skip fully-condensed ended sessions early
169→						if state.FullyCondensed && state.Phase == session.PhaseEnded {
170→							continue
171→						}
172→						seen[sessionID] = true
173→						sessions = append(sessions, state)
174→					}
175→				}
176→			}
177→		}
178→	}
179→
180→	// Step 2: Scan state files for sessions not yet in the shadow tree.
181→	// This catches two cases:
182→	//   a) ACTIVE sessions that haven't had SaveStep yet (no shadow branch data)
183→	//   b) Non-active sessions with carry-forward files whose BaseCommit matches
184→	//      the parent commit. Carry-forward shadow branches intentionally omit
185→	//      metadata (to avoid sessionHasNewContent false positives), so these
186→	//      sessions are invisible to the shadow tree scan above.
187→	// This is cheap — just JSON parse + field checks, no ref lookups.
188→	store, storeErr := s.getStateStore(ctx)
189→	if storeErr != nil {
190→		logging.Warn(logCtx, "findSessionsFromShadowTree: failed to get state store",
191→			slog.String("error", storeErr.Error()))
192→		return sessions, nil
193→	}
194→	allStates, listErr := store.List(ctx)
195→	if listErr != nil {
196→		logging.Warn(logCtx, "findSessionsFromShadowTree: failed to list session states",
197→			slog.String("error", listErr.Error()))
198→		return sessions, nil
199→	}
200→	for _, state := range allStates {
201→		if seen[state.SessionID] {
202→			continue
203→		}
204→		if state.WorktreePath != worktreePath {
205→			continue
206→		}
207→		// Case (a): ACTIVE sessions without shadow branch data
208→		if state.Phase.IsActive() {
209→			seen[state.SessionID] = true
210→			sessions = append(sessions, state)
211→			continue
212→		}
213→		// Case (b): Non-active sessions with carry-forward files on this shadow branch
214→		if parentCommitHash != "" && state.BaseCommit == parentCommitHash && len(state.FilesTouched) > 0 {
215→			if state.FullyCondensed && state.Phase == session.PhaseEnded {
216→				continue
217→			}
218→			seen[state.SessionID] = true
219→			sessions = append(sessions, state)
220→		}
221→	}
222→
223→	return sessions, nil
224→}
