226→// findActiveSessionsForWorktree scans state files and returns only ACTIVE-phase
227→// sessions for the given worktree. This is cheap — no ref lookups needed, just
228→// JSON parse + phase check.
229→func (s *ManualCommitStrategy) findActiveSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
230→	store, err := s.getStateStore(ctx)
231→	if err != nil {
232→		return nil, fmt.Errorf("failed to get state store: %w", err)
233→	}
234→
235→	allStates, err := store.List(ctx)
236→	if err != nil {
237→		return nil, fmt.Errorf("failed to list session states: %w", err)
238→	}
239→
240→	var matching []*SessionState
241→	for _, state := range allStates {
242→		if state.Phase.IsActive() && state.WorktreePath == worktreePath {
243→			matching = append(matching, state)
244→		}
245→	}
246→	return matching, nil
247→}
