249→// extractSessionIDsFromTree reads the shadow branch tree to find session IDs
250→// stored under .entire/metadata/<session-id>/ directories.
251→func extractSessionIDsFromTree(tree *object.Tree) []string {
252→	// Navigate to .entire/metadata subtree
253→	metadataTree, err := tree.Tree(paths.EntireMetadataDir)
254→	if err != nil {
255→		return nil
256→	}
257→
258→	var sessionIDs []string
259→	for _, entry := range metadataTree.Entries {
260→		// Session IDs are directory entries under .entire/metadata/
261→		if entry.Mode == filemode.Dir {
262→			sessionIDs = append(sessionIDs, entry.Name)
263→		}
264→	}
265→	return sessionIDs
266→}
