296→// CountOtherActiveSessionsWithCheckpoints counts how many other active sessions
297→// from the SAME worktree (different from currentSessionID) have created checkpoints
298→// on the SAME base commit (current HEAD). This is used to show an informational message
299→// about concurrent sessions that will be included in the next commit.
300→// Returns 0, nil if no such sessions exist.
301→func (s *ManualCommitStrategy) CountOtherActiveSessionsWithCheckpoints(ctx context.Context, currentSessionID string) (int, error) {
302→	currentWorktree, err := paths.WorktreeRoot(ctx)
303→	if err != nil {
304→		return 0, fmt.Errorf("failed to get worktree root: %w", err)
305→	}
306→
307→	// Get current HEAD to compare with session base commits
308→	repo, err := OpenRepository(ctx)
309→	if err != nil {
310→		return 0, err
311→	}
312→	head, err := repo.Head()
313→	if err != nil {
314→		return 0, fmt.Errorf("failed to get HEAD: %w", err)
315→	}
316→	currentHead := head.Hash().String()
317→
318→	allStates, err := s.listAllSessionStates(ctx)
319→	if err != nil {
320→		return 0, err
321→	}
322→
323→	count := 0
324→	for _, state := range allStates {
325→		// Only consider sessions from the same worktree with checkpoints
326→		// AND based on the same commit (current HEAD)
327→		// Sessions from different base commits are independent and shouldn't be counted
328→		if state.SessionID != currentSessionID &&
329→			state.WorktreePath == currentWorktree &&
330→			state.StepCount > 0 &&
331→			state.BaseCommit == currentHead {
332→			count++
333→		}
334→	}
335→	return count, nil
336→}
