401→// getShadowBranchNameForCommit returns the shadow branch name for the given base commit and worktree ID.
402→// worktreeID should be empty for the main worktree or the internal git worktree name for linked worktrees.
403→func getShadowBranchNameForCommit(baseCommit, worktreeID string) string {
404→	return checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID)
405→}
