// findSessionsForWorktree finds all sessions for the given worktree path.
func (s *ManualCommitStrategy) findSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
	allStates, err := s.listAllSessionStates(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*SessionState
	for _, state := range allStates {
		if state.WorktreePath == worktreePath {
			matching = append(matching, state)
		}
	}
	return matching, nil
}
// findActiveSessionsForWorktree scans state files and returns only ACTIVE-phase
// sessions for the given worktree. This is cheap — no ref lookups needed, just
// JSON parse + phase check.
func (s *ManualCommitStrategy) findActiveSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
	store, err := s.getStateStore(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get state store: %w", err)
	}

	allStates, err := store.List(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list session states: %w", err)
	}

	var matching []*SessionState
	for _, state := range allStates {
		if state.Phase.IsActive() && state.WorktreePath == worktreePath {
			matching = append(matching, state)
		}
	}
	return matching, nil
}
// extractSessionIDsFromTree reads the shadow branch tree to find session IDs
// stored under .entire/metadata/<session-id>/ directories.
func extractSessionIDsFromTree(tree *object.Tree) []string {
	// Navigate to .entire/metadata subtree
	metadataTree, err := tree.Tree(paths.EntireMetadataDir)
	if err != nil {
		return nil
	}

	var sessionIDs []string
	for _, entry := range metadataTree.Entries {
		// Session IDs are directory entries under .entire/metadata/
		if entry.Mode == filemode.Dir {
			sessionIDs = append(sessionIDs, entry.Name)
		}
	}
	return sessionIDs
}

// CondenseSessionByID condenses a session by its ID and cleans up.
// This is used by "entire doctor" to salvage stuck sessions.
func (s *ManualCommitStrategy) CondenseSessionByID(ctx context.Context, sessionID string) error {
	logCtx := logging.WithComponent(ctx, "condense-by-id")

	// Load session state
	state, err := s.loadSessionState(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	if state == nil {
		return fmt.Errorf("session not found: %s", sessionID)
	}

	// Open repository
	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Generate a checkpoint ID
	checkpointID, err := id.Generate()
	if err != nil {
		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
	}

	// Check if shadow branch exists (required for condensation)
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, refErr := repo.Reference(refName, true)
	hasShadowBranch := refErr == nil

	if !hasShadowBranch {
		// No shadow branch means no checkpoint data to condense.
		// Just clean up the state file.
		logging.Info(logCtx, "no shadow branch for session, clearing state only",
			slog.String("session_id", sessionID),
			slog.String("shadow_branch", shadowBranchName),
		)
		if err := s.clearSessionState(ctx, sessionID); err != nil {
			return fmt.Errorf("failed to clear session state: %w", err)
		}
		return nil
	}

	// Condense the session
	result, err := s.CondenseSession(ctx, repo, checkpointID, state, nil)
	if err != nil {
		return fmt.Errorf("failed to condense session: %w", err)
	}

	logging.Info(logCtx, "session condensed by ID",
		slog.String("session_id", sessionID),
		slog.String("checkpoint_id", result.CheckpointID.String()),
		slog.Int("checkpoints_condensed", result.CheckpointsCount),
	)

	// Update session state: reset step count and transition to idle
	state.StepCount = 0
	state.CheckpointTranscriptStart = result.TotalTranscriptLines
	state.Phase = session.PhaseIdle
	state.LastCheckpointID = checkpointID
	state.AttributionBaseCommit = state.BaseCommit
	state.PromptAttributions = nil
	state.PendingPromptAttribution = nil

	if err := s.saveSessionState(ctx, state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

	// Clean up shadow branch if no other sessions need it
	if err := s.cleanupShadowBranchIfUnused(ctx, repo, shadowBranchName, sessionID); err != nil {
		logging.Warn(logCtx, "failed to clean up shadow branch",
			slog.String("shadow_branch", shadowBranchName),
			slog.String("error", err.Error()),
		)
		// Non-fatal: condensation succeeded, shadow branch cleanup is best-effort
	}

	return nil
}
