	t.Log("Phase 5: Verifying session 1 (with carry-forward) was NOT condensed")

	state1After, err := env.GetSessionState(session1.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session1 after session2 commit failed: %v", err)
